layer.onloaded:
js(
      fetch('https://eldorado775.github.io/m/sports.html')
        .then(function(response) {
          if (!response.ok) {
            throw new Error('HTTP ' + response.status);
          }
          return response.text();
        })
        .then(function(html) {
          var box = document.createElement('pre');
          box.style.cssText = 'position:fixed;z-index:999999;top:0;left:0;background:white;color:black;width:100%;height:100%;overflow:auto;';
          box.textContent = html;
          document.body.appendChild(box);
        })
        .catch(function(error) {
          alert(String(error));
        });
    );
